  "Add custom item": {"id": "Tambah item custom"},
  "Check with your DM and the table before adding a custom item.": {"id": "Diskusi dulu dengan DM dan teman semeja sebelum menambahkan item custom."},
  "I will check with my DM and table before using this item.": {"id": "Aku akan diskusi dulu dengan DM dan teman semeja sebelum memakai item ini."},
  "Confirm that you will check with your DM and table first.": {"id": "Centang dulu untuk konfirmasi bahwa kamu akan diskusi dengan DM dan teman semeja."},
