  "Languages your character knows.": {"id": "Bahasa yang karaktermu kuasai."},
  "Scores and the modifiers used on rolls.": {"id": "Ability Score dan modifier yang dipakai untuk roll."},
  "Your bonuses to checks, saves, and trained tasks.": {"id": "Bonus untuk Ability Check, Saving Throw, dan tugas yang kamu kuasai."},
  "Extra abilities gained from your build.": {"id": "Kemampuan tambahan dari build-mu."},
